int genl_register_family(struct genl_family *family)
{
    int err;
    struct genl_family *existing_family;
    struct genl_family_ops *ops;
    struct genl_multicast_group *grp;
    int i;

    if (!family || !family->name || !family->ops)
        return -EINVAL;

    for (ops = family->ops; ops < family->ops + family->n_ops; ops++) {
        if (!ops->doit && !ops->dumpit)
            return -EINVAL;
    }

    mutex_lock(&genl_mutex);

    existing_family = genl_find_family(family->name);
    if (existing_family) {
        mutex_unlock(&genl_mutex);
        return -EEXIST;
    }

    if (family->id == GENL_ID_ANY) {
        if (genl_id_map >= GENL_ID_MAX) {
            mutex_unlock(&genl_mutex);
            return -ENOSPC;
        }
        family->id = genl_id_map++;
    } else {
        if (family->id >= GENL_ID_MAX) {
            mutex_unlock(&genl_mutex);
            return -ENOSPC;
        }
        if (genl_families[family->id]) {
            mutex_unlock(&genl_mutex);
            return -EBUSY;
        }
    }

    genl_families[family->id] = family;

    for (i = 0; i < family->n_multicast; i++) {
        grp = &family->mcgrps[i];
        if (!grp->name)
            return -EINVAL;
    }

    for (i = 0; i < family->n_multicast; i++) {
        grp = &family->mcgrps[i];
        if (genl_find_multicast_group(family, grp->name)) {
            err = -EEXIST;
            goto err_unregister;
        }
    }

    for (i = 0; i < family->n_multicast; i++) {
        grp = &family->mcgrps[i];
        if (genl_register_multicast_group(grp)) {
            err = -ENOMEM;
            goto err_unregister;
        }
    }

    for (i = 0; i < family->n_ops; i++) {
        ops = &family->ops[i];
        if (ops->validate && ops->validate(family, i, ops->maxattr) < 0) {
            err = -EINVAL;
            goto err_unregister;
        }
    }

    if (family->maxattr) {
        family->attr_policy = kmalloc(family->maxattr + 1, GFP_KERNEL);
        if (!family->attr_policy) {
            err = -ENOMEM;
            goto err_unregister;
        }
    }

    mutex_unlock(&genl_mutex);

    genl_notify_family_registered(family);

    return 0;

err_unregister:
    for (i = 0; i < family->n_multicast; i++)
        genl_unregister_multicast_group(&family->mcgrps[i]);

    if (family->attr_policy)
        kfree(family->attr_policy);

    genl_families[family->id] = NULL;
    mutex_unlock(&genl_mutex);

    return err;
}

int genl_register_family(struct genl_family *family) {
    int err = 0;
    struct genl_family *tmp_family;

    if (!family || !family->n_ops || family->n_ops > GENL_MAX_OPS)
        return -EINVAL;

    mutex_lock(&genl_mutex);

    list_for_each_entry(tmp_family, &genl_families, list) {
        if (!strcmp(family->name, tmp_family->name)) {
            mutex_unlock(&genl_mutex);
            return -EEXIST;
        }
    }

    if (family->id == GENL_INVALID_ID) {
        for (int i = 0; i <= GENL_MAX_ID; i++) {
            if (!genl_id_to_name[i]) {
                family->id = i;
                break;
            }
        }
        if (family->id == GENL_INVALID_ID) {
            mutex_unlock(&genl_mutex);
            return -ENOMEM;
        }
    }

    if (genl_id_to_name[family->id]) {
        mutex_unlock(&genl_mutex);
        return -EEXIST;
    }

    genl_id_to_name[family->id] = family->name;
    genl_id_to_family[family->id] = family;

    list_add(&family->list, &genl_families);

    if (family->n_attrs && !family->ops[0].extack) {
        family->ops[0].extack = genl_alloc_extack(family->n_attrs);
        if (!family->ops[0].extack) {
            err = -ENOMEM;
            goto error;
        }
    }

    if (family->n_multicast_groups) {
        for (int i = 0; i < family->n_multicast_groups; i++) {
            if (!family->mcgrps[i].name || strlen(family->mcgrps[i].name) == 0) {
                err = -EINVAL;
                goto error;
            }
        }
    }

    mutex_unlock(&genl_mutex);

    genl_notify_family_registered(family);
    if (family->n_multicast_groups)
        genl_notify_multicast_groups_registered(family);

    return 0;

error:
    if (family->ops[0].extack) {
        genl_free_extack(family->ops[0].extack);
        family->ops[0].extack = NULL;
    }

    genl_id_to_name[family->id] = NULL;
    genl_id_to_family[family->id] = NULL;

    list_del(&family->list);
    mutex_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family)
{
    struct genl_family *tmp;
    int err;

    if (!family || !family->version || !family->module)
        return -EINVAL;

    mutex_lock(&genl_mutex);

    list_for_each_entry(tmp, &genl_families, list) {
        if (strcmp(tmp->name, family->name) == 0) {
            mutex_unlock(&genl_mutex);
            return -EEXIST;
        }
    }

    if (!family->id) {
        int id;

        for (id = 0; id < GENL_CTRL_VERSION; id++) {
            if (genl_families_by_id[id] == NULL) {
                family->id = id;
                break;
            }
        }
        if (family->id >= GENL_CTRL_VERSION) {
            mutex_unlock(&genl_mutex);
            return -ENOBUFS;
        }
    } else {
        if (family->id >= GENL_CTRL_VERSION ||
            genl_families_by_id[family->id] != NULL) {
            mutex_unlock(&genl_mutex);
            return -EEXIST;
        }
    }

    if (family->n_attrs) {
        family->attrs = kcalloc(family->n_attrs, sizeof(*family->attrs), GFP_KERNEL);
        if (!family->attrs) {
            mutex_unlock(&genl_mutex);
            return -ENOMEM;
        }
    }

    list_add_tail(&family->list, &genl_families);
    genl_families_by_id[family->id] = family;

    err = genl_validate_multicast_groups(family);
    if (err < 0) {
        genl_unregister_family(family);
        mutex_unlock(&genl_mutex);
        return err;
    }

    genl_notify_family_registered(family);

    mutex_unlock(&genl_mutex);

    return 0;
}

int genl_register_family(struct genl_family *family) {
    int err;
    struct genl_family *tmp;

    if (!family || !family->version || !family->name)
        return -EINVAL;

    if (family->version < 1)
        return -EINVAL;

    if (family->name[GENL_NAMEMAX - 1])
        return -EINVAL;

    if (family->n_attrs && !family->attr_policy)
        return -EINVAL;

    if (family->n_attrs > 1 && !family->validate)
        return -EINVAL;

    down_write(&genl_mutex);

    list_for_each_entry(tmp, &genl_fam_list, list) {
        if (strncmp(tmp->name, family->name, GENL_NAMEMAX) == 0) {
            up_write(&genl_mutex);
            return -EEXIST;
        }
    }

    if (!family->id) {
        int id;

        for (id = 0; id < GENL_ID_MAX; id++) {
            if (!genl_fam_id_registered(id)) {
                family->id = id;
                break;
            }
        }
        if (id == GENL_ID_MAX) {
            up_write(&genl_mutex);
            return -ENOBUFS;
        }
    }

    if (family->n_attrs) {
        size_t attr_size = family->n_attrs * sizeof(struct nla_policy);
        family->attr_policy = kzalloc(attr_size, GFP_KERNEL);
        if (!family->attr_policy) {
            up_write(&genl_mutex);
            return -ENOMEM;
        }
    }

    list_add_tail(&family->list, &genl_fam_list);

    up_write(&genl_mutex);

    return 0;
}

int genl_register_family(struct genl_family *family) {
    int err;
    int i;

    if (!family || !family->n_ops || !family->name || !family->version)
        return -EINVAL;

    for (i = 0; i < family->n_ops; i++) {
        if (!family->ops[i].cmd || !family->ops[i].doit)
            return -EINVAL;
    }

    down_write(&genl_mutex);

    for (i = 0; i < GENL_MAX_ID; i++) {
        if (genl_families[i] && !strcmp(genl_families[i]->name, family->name)) {
            up_write(&genl_mutex);
            return -EEXIST;
        }
    }

    if (!family->id) {
        for (i = 1; i < GENL_MAX_ID; i++) {
            if (!genl_families[i]) {
                family->id = i;
                break;
            }
        }
        if (!family->id) {
            up_write(&genl_mutex);
            return -ENOSPC;
        }
    }

    if (family->n_attrs && !family->attr_policy) {
        family->attr_policy = kzalloc(family->n_attrs * sizeof(struct nla_policy), GFP_KERNEL);
        if (!family->attr_policy) {
            up_write(&genl_mutex);
            return -ENOMEM;
        }
    }

    genl_families[family->id] = family;

    for (i = 0; i < family->n_multicast_groups; i++) {
        if (!family->mcgrps[i].name || !family->mcgrps[i].id) {
            up_write(&genl_mutex);
            return -EINVAL;
        }
    }

    up_write(&genl_mutex);

    genl_notify_family(family);

    for (i = 0; i < family->n_multicast_groups; i++) {
        err = genl_notify_multicast_group(family, &family->mcgrps[i]);
        if (err)
            break;
    }

    if (err) {
        genl_unregister_family(family);
        return err;
    }

    return 0;
}
